  "pandas.io.formats.style.Styler.set_uuid": ["Set the identifier used to distinguish the generated table and its HTML elements.", "Styler.set_uuid(uuid)", null, "ဇယားနဲ့ ဇယားထဲက HTML element တွေကို ခွဲခေါ်ဖို့ identifier သတ်မှတ်ပေးပါတယ်။"],
  "pandas.io.formats.style.Styler.text_gradient": ["Color cell text according to numeric values and the selected color map.", "Styler.text_gradient([cmap, low, high, ...])", null, "ကိန်းဂဏန်းတန်ဖိုးနဲ့ ရွေးထားတဲ့ color map အလိုက် cell ထဲက စာသားကို အရောင်ပြောင်းပေးပါတယ်။"],
  "pandas.io.formats.style.Styler.to_excel": ["Write the receiver to an Excel sheet. Use ExcelWriter to manage multiple sheets in one workbook.", "Styler.to_excel(excel_writer[, sheet_name, ...])", null, "ဒေတာကို Excel sheet ထဲ ရေးပေးပါတယ်။ Workbook တစ်ခုထဲမှာ sheet အများကြီး ရေးမယ်ဆို ExcelWriter သုံးပါ။"],
  "pandas.io.formats.style.Styler.to_html": ["Render the receiver as an HTML table. A Styler includes applicable styling rules in its output.", "Styler.to_html([buf, table_uuid, ...])", null, "ဒေတာကို HTML ဇယားအဖြစ် ထုတ်ပေးပါတယ်။ Styler ရဲ့ output မှာ သတ်မှတ်ထားတဲ့ style တွေပါ ပါလာပါတယ်။"],
  "pandas.io.formats.style.Styler.to_latex": ["Produce a LaTeX table representation of the receiver.", "Styler.to_latex([buf, column_format, ...])", null, "ဒေတာကို LaTeX ဇယားပုံစံနဲ့ ထုတ်ပေးပါတယ်။"],
  "pandas.io.formats.style.Styler.to_string": ["Return a human-readable textual representation or write it to the supplied buffer.", "Styler.to_string([buf, encoding, ...])", null, "ဖတ်ရှုလို့လွယ်တဲ့ စာသားအဖြစ် ပြန်ပေးပါတယ်။ Buffer ထည့်ပေးရင် အဲဒီထဲကို ရေးပေးပါတယ်။"],
  "pandas.io.formats.style.Styler.to_typst": ["Render the styled table as Typst source.", "Styler.to_typst([buf, encoding, ...])", null, "Style သတ်မှတ်ထားတဲ့ ဇယားကို Typst source အဖြစ် ထုတ်ပေးပါတယ်။"],
