  "pandas.Series.cat.codes": ["Get integer positions in the category list. Missing values are represented with -1.", null, null, "တန်ဖိုးတစ်ခုစီ category စာရင်းမှာ ရှိတဲ့ နေရာနံပါတ်ကို ပြန်ပေးပါတယ်။ Missing value အတွက် -1 ပြန်ပေးပါတယ်။"],
  "pandas.Series.cat.ordered": ["Check whether the declared category order is meaningful for comparisons.", null, null, "သတ်မှတ်ထားတဲ့ category အစဉ်ကို နှိုင်းယှဉ်ရာမှာ သုံးထားလား စစ်ပေးပါတယ်။"],
  "pandas.Series.cat.remove_categories": ["Remove selected categories and mark observations using them as missing.", "Series.cat.remove_categories(removals)", null, "ရွေးထားတဲ့ category တွေကို ဖယ်ပြီး အဲဒီ category သုံးထားတဲ့ နေရာတွေကို ပျောက်နေတဲ့တန်ဖိုးအဖြစ် ပြောင်းပါတယ်။"],
  "pandas.Series.cat.remove_unused_categories": ["Remove declared categories that do not occur in the data.", "Series.cat.remove_unused_categories()", null, "ဒေတာထဲမှာ အသုံးမပြုထားတဲ့ category တွေကို စာရင်းထဲက ဖယ်ပါတယ်။"],
  "pandas.Series.cat.rename_categories": ["Change the labels of categories and preserve the underlying assignments.", "Series.cat.rename_categories(new_categories)", null, "တန်ဖိုးတစ်ခုစီရဲ့ category ကို အတူတူထားပြီး category အမည်တွေကို ပြောင်းပါတယ်။"],
  "pandas.Series.cat.reorder_categories": ["Set the order of existing categories without changing which category each value belongs to.", "Series.cat.reorder_categories(new_categories)", null, "တန်ဖိုးတစ်ခုစီရဲ့ category ကို အတူတူထားပြီး category အစဉ်ကို ပြန်သတ်မှတ်ပါတယ်။"],
  "pandas.Series.cat.set_categories": ["Replace the permitted categories. Observations outside the new set can become missing.", "Series.cat.set_categories(new_categories[, ...])", null, "လက်ခံမယ့် category စာရင်းကို ပြောင်းပါတယ်။ စာရင်းအသစ်ထဲ မပါတဲ့ တန်ဖိုးတွေက missing value ဖြစ်နိုင်ပါတယ်။"],
  "pandas.Series.clip": ["Clamp values to lower or upper limits, leaving values within the limits unchanged.", "Series.clip([lower, upper, axis, inplace])", null, "သတ်မှတ်ထားတဲ့ အနိမ့်ဆုံးအောက် ရောက်တဲ့တန်ဖိုးကို အနိမ့်ဆုံးနဲ့ အစားထိုးပြီး အမြင့်ဆုံးထက် ကျော်တာကို အမြင့်ဆုံးနဲ့ အစားထိုးပါတယ်။ ကြားထဲကတန်ဖိုးတွေကို ဆက်ထားပါတယ်။"],
  "pandas.Series.combine": ["Combine aligned objects using a callable. DataFrame passes columns to the callable and Series passes individual values.", "Series.combine(other, func[, fill_value])", null, "Label အလိုက် ညှိထားတဲ့ object တွေကို function နဲ့ ပေါင်းစပ်ပါတယ်။ DataFrame က column တွေပေးပြီး Series က တန်ဖိုးတစ်ခုချင်းစီ ပေးပါတယ်။"],
  "pandas.Series.combine_first": ["Fill missing positions from a second aligned object while keeping existing valid values.", "Series.combine_first(other)", null, "ရှိပြီးသား တန်ဖိုးတွေကို ဆက်ထားပြီး ပျောက်နေတဲ့ တန်ဖိုးတွေကို တခြား object ထဲက label တူတဲ့တန်ဖိုးနဲ့ ဖြည့်ပါတယ်။"],
  "pandas.Series.compare": ["Display the differences between two equally labeled objects side by side.", "Series.compare(other[, align_axis, ...])", null, "Label တူတဲ့ object နှစ်ခုကြား ကွာခြားတဲ့တန်ဖိုးတွေကို ဘေးချင်းကပ် ပြပါတယ်။"],
  "pandas.Series.convert_dtypes": ["Infer dtypes with support for missing values, such as nullable integers or strings.", "Series.convert_dtypes([infer_objects, ...])", null, "Nullable integer သို့မဟုတ် string လို ပျောက်နေတဲ့ တန်ဖိုးတွေကို လက်ခံတဲ့ dtype တွေ ဖြစ်နိုင်သလား ခန့်မှန်းပေးပါတယ်။"],
  "pandas.Series.copy": ["Make a copy of the receiver. For an HDFStore, copy stored data to a different file.", "Series.copy([deep])", null, "လက်ရှိ object ကို မိတ္တူကူးပါတယ်။ HDFStore မှာ သိမ်းထားတဲ့ ဒေတာကို တခြားဖိုင်တစ်ခုထဲ ကူးနိုင်ပါတယ်။"],
