  "pandas.Series.count": ["Count nonmissing values along the selected axis or within each group or window.", "Series.count()", null, "ရွေးထားတဲ့ axis၊ အုပ်စု သို့မဟုတ် window ထဲမှာ တန်ဖိုးရှိတဲ့ entry တွေကို ရေတွက်ပါတယ်။"],
  "pandas.Series.cov": ["Estimate how pairs of numeric inputs vary together from aligned observations.", "Series.cov(other[, min_periods, ddof])", null, "ကိုက်ညီရာ တန်ဖိုးစုံတွဲတွေကို သုံးပြီး ဂဏန်းဒေတာနှစ်ခု အတူတကွ ပြောင်းလဲပုံ (covariance) ကို တွက်ပါတယ်။"],
  "pandas.Series.cummax": ["Track the largest value encountered up to each position.", "Series.cummax([axis, skipna])", null, "နေရာတစ်ခုစီအထိ တွေ့ထားသမျှထဲက အကြီးဆုံးတန်ဖိုးကို ထုတ်ပေးပါတယ်။"],
  "pandas.Series.cummin": ["Track the smallest value encountered up to each position.", "Series.cummin([axis, skipna])", null, "နေရာတစ်ခုစီအထိ တွေ့ထားသမျှထဲက အငယ်ဆုံးတန်ဖိုးကို ထုတ်ပေးပါတယ်။"],
  "pandas.Series.cumprod": ["Keep a running product in observation order.", "Series.cumprod([axis, skipna])", null, "တန်ဖိုးတွေကို အစဉ်လိုက် ဆက်မြှောက်ပြီး နေရာတစ်ခုစီအထိ ရထားတဲ့ မြှောက်လဒ်ကို ထုတ်ပေးပါတယ်။"],
  "pandas.Series.cumsum": ["Keep a running total in observation order.", "Series.cumsum([axis, skipna])", "orders[\"units\"].cumsum()", "တန်ဖိုးတွေကို အစဉ်လိုက် ဆက်ပေါင်းပြီး နေရာတစ်ခုစီအထိ ရထားတဲ့ စုစုပေါင်းကို ထုတ်ပေးပါတယ်။"],
  "pandas.Series.describe": ["Summarize values with statistics appropriate to their dtype, such as quartiles for numbers or frequencies for categories.", "Series.describe([percentiles, include, exclude])", null, "dtype အလိုက် သင့်တော်တဲ့ စာရင်းကိန်းတွေကို ထုတ်ပေးပါတယ်။ ဥပမာ ဂဏန်းတွေအတွက် quartile၊ category တွေအတွက် အကြိမ်ရေကို တွက်ပေးပါတယ်။"],
