  "pandas.Series.dt.ceil": ["Round timestamps or durations up to a frequency boundary.", "Series.dt.ceil(freq[, ambiguous, nonexistent])", null, "Timestamp သို့မဟုတ် ကြာချိန်ကို သတ်မှတ်ထားတဲ့ frequency ရဲ့ နောက်အမှတ်အထိ ပင့်ပေးပါတယ်။"],
  "pandas.Series.dt.date": ["Extract each calendar date as a standard-library date object.", null, null, "ရက်စွဲတစ်ခုချင်းကို Python standard library ရဲ့ date object အဖြစ် ထုတ်ပေးပါတယ်။"],
  "pandas.Series.dt.day": ["Get the day of the month from each date.", null, null, "ရက်စွဲတစ်ခုစီမှာ အဲဒီလရဲ့ ဘယ်နှရက်မြောက်လဲ ထုတ်ပေးပါတယ်။"],
  "pandas.Series.dt.day_name": ["Get weekday names, optionally using a specified locale.", "Series.dt.day_name([locale])", null, "ရက်သတ္တပတ်ထဲက နေ့အမည်ကို ပြန်ပေးပါတယ်။ ပြမယ့် ဘာသာစကားကို locale နဲ့ သတ်မှတ်နိုင်ပါတယ်။"],
  "pandas.Series.dt.dayofweek": ["Get the weekday number, where Monday is 0 and Sunday is 6.", null, null, "ရက်သတ္တပတ်ထဲက နေ့နံပါတ်ကို ထုတ်ပေးပါတယ်။ တနင်္လာနေ့က 0 ဖြစ်ပြီး တနင်္ဂနွေနေ့က 6 ဖြစ်ပါတယ်။"],
  "pandas.Series.dt.floor": ["Round timestamps or durations down to a frequency boundary.", "Series.dt.floor(freq[, ambiguous, nonexistent])", null, "Timestamp သို့မဟုတ် ကြာချိန်ကို သတ်မှတ်ထားတဲ့ frequency ရဲ့ ရှေ့အမှတ်အထိ ချပေးပါတယ်။"],
  "pandas.Series.dt.isocalendar": ["Get the ISO week-based year, week number and day of the week.", "Series.dt.isocalendar()", null, "ISO စံအရ နှစ်၊ ရက်သတ္တပတ်နံပါတ်နဲ့ ရက်သတ္တပတ်အတွင်း နေ့နံပါတ်ကို ထုတ်ပေးပါတယ်။"],
  "pandas.Series.dt.month": ["Get the calendar month number from 1 to 12.", null, null, "ပြက္ခဒိန်အရ လနံပါတ်ကို 1 ကနေ 12 အထိ ထုတ်ပေးပါတယ်။"],
  "pandas.Series.dt.month_name": ["Get month names, optionally using a specified locale.", "Series.dt.month_name([locale])", null, "လအမည်ကို ပြန်ပေးပါတယ်။ ပြမယ့် ဘာသာစကားကို locale နဲ့ သတ်မှတ်နိုင်ပါတယ်။"],
  "pandas.Series.dt.normalize": ["Set the clock time to midnight while preserving the calendar date and timezone.", "Series.dt.normalize()", null, "ရက်စွဲနဲ့ timezone ကို ထိန်းထားပြီး နာရီအချိန်ကို ညသန်းခေါင်အဖြစ် ပြောင်းပေးပါတယ်။"],
  "pandas.Series.dt.round": ["Round values to a specified precision. For datetime-like objects use a frequency.", "Series.dt.round(freq[, ambiguous, nonexistent])", null, "ကိန်းဂဏန်းကို သတ်မှတ်ထားတဲ့ ဒဿမနေရာအတိုင်း round လုပ်ပေးပါတယ်။ ရက်စွဲနဲ့ အချိန်တန်ဖိုးတွေအတွက် frequency သတ်မှတ်နိုင်ပါတယ်။"],
  "pandas.Series.dt.strftime": ["Format a time value using strftime directives such as %Y-%m-%d. Period.strftime is deprecated in pandas 3.1.1.", "Series.dt.strftime(date_format)", "orders[\"day\"].dt.strftime(\"%Y-%m\")", "ရက်စွဲ၊ အချိန်တွေကို သတ်မှတ်ထားတဲ့ပုံစံနဲ့ စာသားပြောင်းပါတယ်။"],
  "pandas.Series.dt.to_period": ["Convert the datetime values to periods at the supplied frequency.", "Series.dt.to_period([freq])", null, "Datetime တန်ဖိုးတွေကို ထည့်ပေးထားတဲ့ frequency အတိုင်း period တွေအဖြစ် ပြောင်းပေးပါတယ်။"],
  "pandas.Series.dt.to_pydatetime": ["Get a Series of standard-library datetime objects from the timestamp values.", "Series.dt.to_pydatetime()", null, "Timestamp တန်ဖိုးတွေကို Python standard library ရဲ့ datetime object တွေပါတဲ့ Series အဖြစ် ပြောင်းပေးပါတယ်။"],
  "pandas.Series.dt.to_pytimedelta": ["Convert pandas durations to standard-library timedelta objects.", "Series.dt.to_pytimedelta()", null, "pandas ကြာချိန်တန်ဖိုးတွေကို Python standard library ရဲ့ timedelta object တွေအဖြစ် ပြောင်းပေးပါတယ်။"],
