  "pandas.Series.rolling": ["Build a moving window defined by an observation count, time span or custom indexer.", "Series.rolling(window[, min_periods, ...])", "orders[\"units\"].rolling(window=2, min_periods=1).mean()", "Row အရေအတွက် သို့မဟုတ် အချိန်အပိုင်းအခြားအလိုက် ရွေ့နေတဲ့ window ဆောက်ပါတယ်။"],
  "pandas.Series.round": ["Round values to a specified precision. For datetime-like objects use a frequency.", "Series.round([decimals])", null, "ကိန်းဂဏန်းကို သတ်မှတ်ထားတဲ့ ဒဿမနေရာအတိုင်း round လုပ်ပေးပါတယ်။ ရက်စွဲနဲ့ အချိန်တန်ဖိုးတွေအတွက် frequency သတ်မှတ်နိုင်ပါတယ်။"],
  "pandas.Series.rpow": ["Use the supplied values as bases and the object's values as exponents.", "Series.rpow(other[, level, fill_value, axis])", null, "ထည့်လိုက်တဲ့ တန်ဖိုးတွေကို အခြေကိန်း၊ မူလတန်ဖိုးတွေကို ထပ်ညွှန်းကိန်းအဖြစ် သုံးပြီး ထပ်တင်ပေးပါတယ်။"],
  "pandas.Series.rsub": ["Subtract the object's values from the supplied value.", "Series.rsub(other[, level, fill_value, axis])", null, "ထည့်လိုက်တဲ့ တန်ဖိုးထဲက မူလတန်ဖိုးတစ်ခုစီကို နုတ်ပေးပါတယ်။"],
  "pandas.Series.rtruediv": ["Use the supplied value as the numerator in true division.", "Series.rtruediv(other[, level, fill_value, axis])", null, "ထည့်လိုက်တဲ့ တန်ဖိုးကို စားတည်ကိန်းအဖြစ် သုံးပြီး ဒဿမ ထည့်တွက်တဲ့ စားလဒ် ထုတ်ပေးပါတယ်။"],
  "pandas.Series.sample": ["Randomly select rows, entries or columns. Set random_state for repeatable results.", "Series.sample([n, frac, replace, weights, ...])", null, "Row၊ entry သို့မဟုတ် column တွေကို ကျပန်းရွေးပါတယ်။ ထပ်စမ်းတိုင်း တူတဲ့ရလဒ်လိုရင် random_state ပေးပါ။"],
  "pandas.Series.searchsorted": ["Get the insertion positions that preserve the order of sorted data.", "Series.searchsorted(value[, side, sorter])", null, "အစဉ်လိုက် စီထားတဲ့ ဒေတာထဲကို တန်ဖိုးအသစ် ထည့်တဲ့အခါ အစဉ်မပျက်စေမယ့် နေရာတွေကို ရှာပေးပါတယ်။"],
  "pandas.Series.sem": ["Calculate the standard error of the mean for the selected data.", "Series.sem(*[, axis, skipna, ddof, numeric_only])", null, "ရွေးထားတဲ့ ဒေတာအတွက် ပျမ်းမျှရဲ့ standard error ကို တွက်ပေးပါတယ်။"],
  "pandas.Series.set_axis": ["Replace all labels on an axis with a new collection of equal length.", "Series.set_axis(labels, *[, axis, copy])", null, "Axis တစ်ခုမှာရှိတဲ့ label အားလုံးကို အရေအတွက်တူတဲ့ label အသစ်တွေနဲ့ အစားထိုးပေးပါတယ်။"],
  "pandas.Series.set_flags": ["Get an object with changed flags, such as whether duplicate labels are allowed.", "Series.set_flags(*[, copy, ...])", null, "Flag ပြောင်းထားတဲ့ object ကို ပြန်ပေးပါတယ်။ ဥပမာ label ထပ်နေတာကို လက်ခံမလား သတ်မှတ်နိုင်ပါတယ်။"],
  "pandas.Series.shape": ["Get the number of entries as a one-element tuple.", null, null, "Entry အရေအတွက်ကို element တစ်ခုပါတဲ့ tuple အဖြစ် ပြန်ပေးပါတယ်။"],
  "pandas.Series.shift": ["Move values by a positional offset. With a time frequency, move the labels instead.", "Series.shift([periods, freq, axis, ...])", "orders[\"units\"].shift(1)", "တန်ဖိုးတွေကို သတ်မှတ်ထားတဲ့ နေရာအရေအတွက်အတိုင်း ရွှေ့ပါတယ်။ အချိန် frequency ပေးရင် label တွေကို ရွှေ့ပါတယ်။"],
  "pandas.Series.size": ["Get the number of values, including missing values.", null, null, "Missing value အပါအဝင် တန်ဖိုးအရေအတွက်ကို ပြန်ပေးပါတယ်။"],
  "pandas.Series.skew": ["Estimate how asymmetric a numeric distribution is.", "Series.skew(*[, axis, skipna, numeric_only])", null, "ဂဏန်းဒေတာ ဖြန့်ကျက်ပုံက ဘယ်လောက် မညီမျှလဲဆိုတာ skewness နဲ့ တွက်ပါတယ်။"],
  "pandas.Series.sort_index": ["Order rows or columns by their labels.", "Series.sort_index(*[, axis, level, ...])", null, "Row သို့မဟုတ် column တွေကို သူတို့ရဲ့ label အလိုက် စီပေးပါတယ်။"],
  "pandas.Series.sort_values": ["Order items by one or more data values, controlling missing-value placement.", "Series.sort_values(*[, axis, ascending, ...])", null, "ဒေတာတန်ဖိုးတစ်ခု သို့မဟုတ် အများအပြားအလိုက် စီပေးပါတယ်။ Missing value တွေကို ဘယ်နေရာမှာ ထားမလဲ ရွေးနိုင်ပါတယ်။"],
  "pandas.Series.sparse": ["Get the accessor for operations on sparse values.", null, null, "Sparse ဒေတာနဲ့ သက်ဆိုင်တဲ့ method နဲ့ property တွေကို သုံးနိုင်တဲ့ accessor ကို ပေးပါတယ်။"],
  "pandas.Series.sparse.from_coo": ["Construct a sparse Series from a SciPy coordinate matrix.", "Series.sparse.from_coo(A[, dense_index])", null, "SciPy coordinate matrix ကနေ sparse Series တည်ဆောက်ပေးပါတယ်။"],
