  "pandas.Series.str.cat": ["Join all strings into one value, or concatenate each row with aligned strings from other inputs.", "Series.str.cat([others, sep, na_rep, join])", null, "စာသားအားလုံးကို စာသားတစ်ခုအဖြစ် ဆက်ပေးပါတယ်။ အခြား input တွေထည့်ရင် label တန်းညှိပြီး row တစ်ခုချင်း ဆက်နိုင်ပါတယ်။"],
  "pandas.Series.str.center": ["Pad both sides of each string to reach a minimum width.", "Series.str.center(width[, fillchar])", null, "စာသားတစ်ခုစီကို အနည်းဆုံးလိုတဲ့ အရှည်အထိ နှစ်ဖက်လုံးမှာ စာလုံးဖြည့်ပေးပါတယ်။"],
  "pandas.Series.str.contains": ["Check whether each string contains a pattern. Set regex=False to match text literally.", "Series.str.contains(pat[, case, flags, na, ...])", "orders[\"team\"].str.contains(\"north\", case=False, regex=False)", "စာသားတစ်ခုစီမှာ pattern ပါသလား စစ်ပါတယ်။ ပုံမှန်စာသားအတိုင်း ရှာချင်ရင် regex=False သုံးပါ။"],
  "pandas.Series.str.count": ["Count nonoverlapping regex matches separately in each string.", "Series.str.count(pat[, flags])", "pd.Series([\"A-A\", \"B-A\"]).str.count(\"A\")", "စာသားတစ်ခုစီမှာ ထပ်နေတဲ့ အပိုင်းတွေ ထပ်မတွက်ဘဲ regex နဲ့ ကိုက်တဲ့ အကြိမ်အရေအတွက်ကို ရေတွက်ပါတယ်။"],
  "pandas.Series.str.decode": ["Decode byte strings to text with a selected character encoding.", "Series.str.decode(encoding[, errors, dtype])", null, "သတ်မှတ်ထားတဲ့ encoding ကို သုံးပြီး bytes ကနေ စာသားအဖြစ် ပြောင်းပေးပါတယ်။"],
  "pandas.Series.str.encode": ["Encode strings as bytes using a selected character encoding.", "Series.str.encode(encoding[, errors])", null, "သတ်မှတ်ထားတဲ့ encoding ကို သုံးပြီး စာသားကနေ bytes အဖြစ် ပြောင်းပေးပါတယ်။"],
  "pandas.Series.str.endswith": ["Check whether each string ends with the supplied suffix or any of the supplied suffixes.", "Series.str.endswith(pat[, na])", null, "စာသားတစ်ခုစီရဲ့ အဆုံးမှာ သတ်မှတ်ထားတဲ့ နောက်ဆက်စာသားတစ်ခုခု ရှိမရှိ စစ်ပါတယ်။"],
