  "pandas.Series.str.extractall": ["Return captures for every pattern match, adding a level to distinguish matches within the same row.", "Series.str.extractall(pat[, flags])", null, "Pattern နဲ့ ကိုက်တဲ့ အကြိမ်တိုင်းက capture group တွေကို ထုတ်ပေးပါတယ်။ Row တစ်ခုတည်းမှာ တွေ့တဲ့ match တွေကို ခွဲဖို့ index level တစ်ခုပါ ထည့်ပေးပါတယ်။"],
  "pandas.Series.str.find": ["Get the first position of a substring, using -1 where it cannot be found.", "Series.str.find(sub[, start, end])", null, "ရှာတဲ့စာသားကို ပထမဆုံး တွေ့တဲ့ နေရာနံပါတ် ပြန်ပေးပါတယ်။ ရှာမတွေ့ရင် -1 ပြန်ပေးပါတယ်။"],
  "pandas.Series.str.findall": ["Collect all nonoverlapping regex matches separately for each string.", "Series.str.findall(pat[, flags])", null, "စာသားတစ်ခုစီမှာ regex နဲ့ ကိုက်ပြီး အပိုင်းချင်း မထပ်တဲ့ match အားလုံးကို စုပေးပါတယ်။"],
  "pandas.Series.str.fullmatch": ["Test whether a regular expression matches the whole string.", "Series.str.fullmatch(pat[, case, flags, na])", null, "စာသားတစ်ခုလုံးက regular expression နဲ့ ကိုက်ညီသလား စစ်ပေးပါတယ်။"],
  "pandas.Series.str.get": ["Extract an element at the given position or key from each string or list-like value.", "Series.str.get(i)", null, "စာသား သို့မဟုတ် list ပုံစံ တန်ဖိုးတစ်ခုစီက သတ်မှတ်ထားတဲ့ နေရာနံပါတ် သို့မဟုတ် key အတိုင်း element တစ်ခု ထုတ်ပေးပါတယ်။"],
  "pandas.Series.str.get_dummies": ["Split each string into tokens and build a separate indicator column for each token.", "Series.str.get_dummies([sep, dtype])", null, "စာသားတစ်ခုစီကို အပိုင်းလိုက် ခွဲပြီး အပိုင်းတစ်မျိုးစီ ပါမပါ ပြတဲ့ indicator column တစ်ခုစီ တည်ဆောက်ပေးပါတယ်။"],
  "pandas.Series.str.index": ["Get the first position of a substring, raising for an unsuccessful lookup.", "Series.str.index(sub[, start, end])", null, "ရှာတဲ့စာသားကို ပထမဆုံး တွေ့တဲ့ နေရာနံပါတ် ပြန်ပေးပါတယ်။ ရှာမတွေ့ရင် error တက်ပါတယ်။"],
  "pandas.Series.str.isalnum": ["Test whether a string has at least one character and every character is a letter or a number.", "Series.str.isalnum()", null, "စာသားမှာ အနည်းဆုံး စာလုံးတစ်လုံးရှိပြီး အားလုံးက အက္ခရာ သို့မဟုတ် ကိန်းဂဏန်းတွေလား စစ်ပေးပါတယ်။"],
  "pandas.Series.str.isalpha": ["Test whether all characters are alphabetic, with empty strings returning false.", "Series.str.isalpha()", null, "ပါဝင်တဲ့ စာလုံးအားလုံးက အက္ခရာတွေလား စစ်ပေးပါတယ်။ အလွတ်စာသားအတွက် False ပြန်ပေးပါတယ်။"],
  "pandas.Series.str.isascii": ["Test whether all characters are in the ASCII character set.", "Series.str.isascii()", null, "ပါဝင်တဲ့ စာလုံးအားလုံး ASCII character set ထဲမှာ ပါမပါ စစ်ပေးပါတယ်။"],
  "pandas.Series.str.isdecimal": ["Test whether every character in a nonempty string is a Unicode decimal digit.", "Series.str.isdecimal()", null, "စာလုံးပါဝင်ပြီး အဲဒီစာလုံးအားလုံး Unicode decimal digit ဖြစ်မဖြစ် စစ်ပေးပါတယ်။"],
  "pandas.Series.str.isdigit": ["Test whether every character in a nonempty string satisfies Unicode's digit rule.", "Series.str.isdigit()", null, "စာလုံးပါဝင်ပြီး စာလုံးအားလုံး Unicode ရဲ့ digit သတ်မှတ်ချက်နဲ့ ကိုက်ညီမညီ စစ်ပေးပါတယ်။"],
  "pandas.Series.str.islower": ["Test whether all cased characters are lowercase and at least one cased character is present.", "Series.str.islower()", null, "စာလုံးအကြီးအသေး ခွဲလို့ရတဲ့ စာလုံးတစ်လုံး အနည်းဆုံးပါပြီး အဲဒီစာလုံးအားလုံး အသေး ဖြစ်မဖြစ် စစ်ပေးပါတယ်။"],
  "pandas.Series.str.isnumeric": ["Test whether every character in a nonempty string has a Unicode numeric value.", "Series.str.isnumeric()", null, "စာလုံးပါဝင်ပြီး အားလုံးမှာ Unicode အရ ကိန်းဂဏန်းတန်ဖိုး ရှိမရှိ စစ်ပေးပါတယ်။"],
